import java.util.Scanner

fun main() {
    val scanner = Scanner(System.`in`)
    val a = scanner.nextInt()
    val b = scanner.nextInt()
    val c = scanner.nextInt()

    val sum = a + b + c
    if (sum % 2 != 0) {
        println("Impossible")
        return
    }

    val s = sum / 2
    val x = s - c
    val y = s - a
    val z = s - b

    if (x < 0 || y < 0 || z < 0) {
        println("Impossible")
    } else {
        println("$x $y $z")
    }
}
